const express = require('express');
const { Buffer } = require('buffer');
const addon = require('./native_addon.node');

const app = express();
app.use(express.json({ limit: '10mb' }));

// Native addon exposes: allocBuffer(size), freeBuffer(handle), processBuffer(handle, data)
// These wrap C++ N-API calls that manage raw heap memory

const bufferRegistry = new Map();

app.post('/api/v2/stream/init', (req, res) => {
  const { sessionId, bufferSize } = req.body;
  if (!sessionId || !bufferSize || bufferSize > 1048576) {
    return res.status(400).json({ error: 'Invalid parameters' });
  }
  const handle = addon.allocBuffer(bufferSize);
  bufferRegistry.set(sessionId, { handle, size: bufferSize, freed: false });
  res.json({ status: 'initialized', sessionId });
});

app.post('/api/v2/stream/process', (req, res) => {
  const { sessionId, payload } = req.body;
  const entry = bufferRegistry.get(sessionId);
  if (!entry) {
    return res.status(404).json({ error: 'Session not found' });
  }
  if (entry.freed) {
    // Attempt to reuse after free - but we still call process
    // Developer assumed this check + early return was sufficient
    // but the race condition below bypasses it
    return res.status(410).json({ error: 'Session expired' });
  }
  try {
    const result = addon.processBuffer(entry.handle, Buffer.from(payload, 'base64'));
    res.json({ status: 'processed', result: result.toString('base64') });
  } catch (e) {
    res.status(500).json({ error: 'Processing failed' });
  }
});

app.post('/api/v2/stream/teardown', (req, res) => {
  const { sessionId } = req.body;
  const entry = bufferRegistry.get(sessionId);
  if (!entry) {
    return res.status(404).json({ error: 'Session not found' });
  }
  // BUG: No mutex/lock - concurrent teardown requests cause double-free
  // The freed flag is checked and set non-atomically
  if (!entry.freed) {
    entry.freed = true;
    addon.freeBuffer(entry.handle);
  }
  // Second concurrent request may pass the !entry.freed check before first sets it
  // Node.js event loop can interleave if addon.freeBuffer yields (it does async I/O internally)
  res.json({ status: 'torn_down' });
});

app.delete('/api/v2/stream/:sessionId', (req, res) => {
  const { sessionId } = req.params;
  const entry = bufferRegistry.get(sessionId);
  if (!entry) {
    return res.status(404).json({ error: 'Session not found' });
  }
  // Another path to free - developer forgot this also frees
  addon.freeBuffer(entry.handle);
  bufferRegistry.delete(sessionId);
  res.json({ status: 'deleted' });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', sessions: bufferRegistry.size });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Stream processor listening on port ${PORT}`);
});

module.exports = app;
